import {
  Box,
  Stack,
  Typography,
} from "@mui/material";

import ForecastContextBar from "../../../components/layout/ForecastContextBar";

import ForecastOverview from "../components/ForecastOverview";


const ForecastPage = () => {
  return (
    <Box
      sx={{
        width: "100%",
        minHeight: "100%",
        bgcolor: "#F5F7FA",

        px: {
          xs: 2,
          sm: 3,
          md: 4,
          lg: 5,
        },

        py: {
          xs: 2,
          md: 4,
        },

        boxSizing: "border-box",
      }}
    >

      <Box
        sx={{
          width: "100%",
          maxWidth: 1600,
          mx: "auto",
        }}
      >

        {/* PAGE HEADER */}

        <Stack
          spacing={0.5}
          mb={4}
        >
          <Typography
            variant="h4"
            fontWeight={800}
            color="#172B4D"
          >
            Forecast
          </Typography>

          <Typography
            variant="body1"
            color="text.secondary"
          >
            Generate, monitor and analyse
            power forecasts across the fleet.
          </Typography>
        </Stack>


        {/* DASHBOARD */}

        <Stack
          spacing={{
            xs: 2.5,
            md: 4,
          }}
        >

          {/* FORECAST CONTEXT */}

          <ForecastContextBar />


          {/* FORECAST INTELLIGENCE */}

          <ForecastOverview />

        </Stack>

      </Box>
    </Box>
  );
};


export default ForecastPage;
